\usetikzlibrary{calc,arrows.meta}
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,text=black,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-0.2,-1.1) rectangle (4.1,3.6);
\coordinate (A) at (0,0);
\coordinate (B) at (3.2,0);
\coordinate (C) at (3.7,{sqrt(3.2*3.2-0.5*0.5)});
\coordinate (D) at (0.5,{sqrt(3.2*3.2-0.5*0.5)});
\draw[line width=0.8pt] (A)--(B)--(C)--(D)--cycle;
\coordinate (MAB) at ($(A)!0.5!(B)$);
\coordinate (MBC) at ($(B)!0.5!(C)$);
\coordinate (MCD) at ($(C)!0.5!(D)$);
\coordinate (MDA) at ($(D)!0.5!(A)$);
\draw[line width=0.4pt] ($(MAB)!1.5mm!90:(B)$)--($(MAB)!1.5mm!-90:(B)$);
\draw[line width=0.4pt] ($(MBC)!1.5mm!90:(C)$)--($(MBC)!1.5mm!-90:(C)$);
\draw[line width=0.4pt] ($(MCD)!1.5mm!90:(D)$)--($(MCD)!1.5mm!-90:(D)$);
\draw[line width=0.4pt] ($(MDA)!1.5mm!90:(A)$)--($(MDA)!1.5mm!-90:(A)$);
\coordinate (Hbottom) at (2.75,0);
\coordinate (Htop) at (2.75,{sqrt(3.2*3.2-0.5*0.5)});
\draw[line width=0.5pt,{Stealth[length=2mm]}-{Stealth[length=2mm]}] (Hbottom)--(Htop) node[midway,left,inner sep=1.5mm] {$4\ \mathrm{cm}$};
\coordinate (Baseleft) at ($(A)+(0,-0.45)$);
\coordinate (Baseright) at ($(B)+(0,-0.45)$);
\draw[line width=0.5pt,{Stealth[length=2mm]}-{Stealth[length=2mm]}] (Baseleft)--(Baseright) node[midway,below,inner sep=1.5mm] {$5\ \mathrm{cm}$};
\end{tikzpicture}

